from collections import deque
def reach_transform(grid):
    sr,sc=next((r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==3)
    dr,dc=sr-4,sc-5
    cand={(r+dr,c+dc) for r,c in source_mask if 0<=r+dr<len(grid) and 0<=c+dc<len(grid[0])}
    free={q for q in cand if grid[q[0]][q[1]]!=2}
    seen={(sr,sc)} if (sr,sc) in free else set(); q=deque(seen)
    while q:
      r,c=q.popleft()
      for z in ((r+1,c),(r-1,c),(r,c+1),(r,c-1)):
       if z in free and z not in seen:seen.add(z);q.append(z)
    out=[row[:] for row in grid]
    for r,c in seen:
      if out[r][c]==0: out[r][c]=3
    return out
